def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def solve():
    good_triples = []
    for x in range(-10, 11):
        for y in range(-10, 11):
            for z in range(-10, 11):
                if x == 0 or y == 0 or z == 0:
                    continue

                # Calculate y^x * z^y * x^z
                # We need to be careful with negative bases and fractional results
                try:
                    # y^x
                    val_y_x = y**x
                    # z^y
                    val_z_y = z**y
                    # x^z
                    val_x_z = x**z

                    res = val_y_x * val_z_y * val_x_z

                    if is_prime(res):
                        good_triples.append((x, y, z, x**2 + y**2 + z**2))
                except ZeroDivisionError:
                    continue
                except OverflowError:
                    continue
                except:
                    continue

    good_triples.sort(key=lambda t: t[3])
    # Remove duplicates (same x^2+y^2+z^2) - wait, the problem says 
    # "We enumerate good triples ... in a way that x_k^2 + y_k^2 + z_k^2 <= x_{k+1}^2 + y_{k+1}^2 + z_{k+1}^2"
    # This means we count ALL good triples. If multiple triples have the same sum of squares,
    # they are still separate entries in the sequence.

    # Let's re-read: "We enumerate good triples as (x1, y1, z1), (x2, y2, z2), ... 
    # in a way that x_k^2 + y_k^2 + z_k^2 <= x_{k+1}^2 + y_{k+1}^2 + z_{k+1}^2 holds"
    # This means the triples are ordered by their sum of squares.
    # So x_{200}^2 + y_{200}^2 + z_{200}^2 is the 200th smallest sum of squares 
    # among ALL good triples.
    # Let's count how many good triples there are for each sum of squares.

    sums = {}
    for x, y, z, s in good_triples:
        sums[s] = sums.get(s, 0) + 1

    sorted_sums = sorted(sums.keys())

    total_count = 0
    for s in sorted_sums:
        total_count += sums[s]
        if total_count >= 200:
            return s, total_count
    return None

print(solve())

